/* A bounded photographic tour: user-driven camera, fixed orientation and explicit exits. */
let walkX=.34,walkActive='women',walkFrame=0;
const SHOP_SECTIONS={men:{brand:'قسم الرجالي',ar:'رجالي',tag:'علاقات الملابس'},women:{brand:'قسم النسائي',ar:'نسائي',tag:'علاقات الملابس'},shoes:{brand:'رفوف الأحذية',ar:'أحذية',tag:'الأحذية'},bags:{brand:'رفوف الحقائب',ar:'حقائب',tag:'الحقائب'},accessories:{brand:'طاولة الإكسسوارات',ar:'إكسسوارات',tag:'الإكسسوارات'}};
function shopBrand(id){return SHOP_SECTIONS[id]||SHOP_SECTIONS.men}
const walkStops=['men','women','accessories','shoes','bags'];
let walkInitialized=false,swipeHintTimer=null;
const WALK_FACADES={men:{x:1,y:20,w:21,h:45},women:{x:26,y:24,w:18,h:32},shoes:{x:62,y:20,w:19,h:24},bags:{x:86,y:13,w:14,h:57},accessories:{x:43,y:51,w:30,h:39}};
function walkHome(){return `<section class="walk-world airy-world" id="walkWorld" aria-label="داخل محل LOOP"><div class="walk-viewport" id="walkViewport" tabindex="0" aria-label="اسحب لاستكشاف أقسام المحل، أو استخدم الأسهم"><div class="walk-scene" id="walkScene"><img src="assets/loop-shop-interior.png" alt="داخل محل LOOP: علاقات ملابس ورفوف للأحذية والحقائب وطاولة إكسسوارات" draggable="false">${DEPARTMENTS.map(d=>{const f=WALK_FACADES[d.id];return `<button class="walk-door" style="left:${f.x}%;top:${f.y}%;width:${f.w}%;height:${f.h}%" data-action="walk-target" data-department="${d.id}" aria-label="دخول ${shopBrand(d.id).brand}، ${d.name}"><span class="section-hotspot"><i></i><strong>${d.name}</strong><span aria-hidden="true">←</span></span></button>`}).join('')}</div></div><div class="walk-vignette"></div><div class="swipe-edges" id="swipeEdges" aria-hidden="true"><span class="edge-cue edge-left">‹</span><span class="edge-cue edge-right">›</span></div><div class="swipe-coach" id="swipeCoach" hidden><div class="swipe-gesture" aria-hidden="true"><span>‹</span><svg viewBox="0 0 48 48"><path d="M17 25V12a3 3 0 0 1 6 0v11-5a3 3 0 0 1 6 0v6-3a3 3 0 0 1 6 0v5-2a3 3 0 0 1 6 0v8c0 8-5 12-12 12h-2c-5 0-8-3-11-7l-7-9a3 3 0 0 1 5-4l3 3"/></svg><span>›</span></div><strong>اسحب يميناً ويساراً</strong><span>واضغط على القسم لتتسوّق</span></div><div class="swipe-position" aria-hidden="true"><span id="swipeSectionName">نسائي</span><div>${walkStops.map(id=>`<i data-position="${id}"></i>`).join('')}</div></div><div class="walk-top"><div class="walk-location" hidden><span id="walkLocation"></span></div><button data-action="walk-fullscreen" id="walkFullscreen" aria-label="تفعيل ملء الشاشة">⛶</button></div><button class="walk-lateral walk-left" data-action="walk-step" data-direction="-1" aria-label="القسم السابق">‹</button><button class="walk-lateral walk-right" data-action="walk-step" data-direction="1" aria-label="القسم التالي">›</button><div class="walk-hint" id="walkHint"><span>اضغط على أي قسم لتصفّح منتجاته</span><button data-action="walk-dismiss" aria-label="إخفاء الإرشاد">×</button></div><div class="walk-bottom"><div class="walk-destination"><span class="walk-destination-label">داخل محل LOOP <span id="walkShopTag" hidden></span></span><div class="walk-destination-row"><div><h1 id="walkTitle">قسم النسائي</h1><p id="walkDescription">أزياء نسائية</p></div><button class="walk-enter" data-action="walk-enter" id="walkEnter">تسوّق القسم ${icon('arrow')}</button></div></div></div><button class="airy-map" data-action="walk-map">${icon('box')} الأقسام</button><nav class="airy-dock" aria-label="التنقل الرئيسي"><a href="#home" aria-current="page">${icon('box')}<span>المحل</span></a><button data-action="walk-map">${icon('menu')}<span>الأقسام</span></button><button data-action="cart">${icon('bag')}<span>الحقيبة</span></button></nav></section>`}
function walkBounds(width,height,x){const w=Math.max(width,height*1.5),h=w/1.5,half=width/w/2,clamped=Math.max(half,Math.min(1-half,x));return{w,h,x:clamped,left:width/2-clamped*w,top:(height-h)*.48}}
function paintWalk(){walkFrame=0;const view=document.getElementById('walkViewport'),scene=document.getElementById('walkScene');if(!view||!scene)return;const c=walkBounds(view.clientWidth,view.clientHeight,walkX);walkX=c.x;scene.style.width=c.w+'px';scene.style.height=c.h+'px';scene.style.transform=`translate3d(${c.left}px,${c.top}px,0)`;const d=DEPARTMENTS.find(d=>d.id===walkActive)||DEPARTMENTS[0];document.getElementById('walkTitle').textContent=shopBrand(d.id).brand;document.getElementById('walkShopTag').textContent=shopBrand(d.id).tag;document.getElementById('walkDescription').textContent=({men:'أزياء رجالية',women:'أزياء نسائية',shoes:'أحذية',bags:'حقائب',accessories:'نظارات وقبعات وإكسسوارات'})[d.id]||d.name;document.getElementById('walkLocation').textContent='داخل المحل'+' · '+shopBrand(d.id).ar;document.querySelectorAll('.walk-door').forEach(b=>{const active=b.dataset.department===d.id;b.classList.toggle('active',active);b.setAttribute('aria-label','تصفح قسم '+shopBrand(b.dataset.department).ar)});document.querySelectorAll('.walk-mini button').forEach(b=>{const active=b.dataset.department===d.id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.getElementById('swipeSectionName').textContent=d.name;document.querySelectorAll('[data-position]').forEach(dot=>dot.classList.toggle('active',dot.dataset.position===walkActive));const edges=document.getElementById('swipeEdges');edges.classList.toggle('at-start',c.left>=-1);edges.classList.toggle('at-end',c.left+c.w<=view.clientWidth+1);const idx=walkStops.indexOf(walkActive);document.querySelector('.walk-left').disabled=idx===0;document.querySelector('.walk-right').disabled=idx===walkStops.length-1;}
function requestWalkPaint(){if(!walkFrame)walkFrame=requestAnimationFrame(paintWalk)}
function walkTo(id){const d=DEPARTMENTS.find(d=>d.id===id);if(!d)return;walkActive=id;walkX=d.x/100;document.getElementById('walkScene')?.classList.remove('dragging');paintWalk();dismissWalkHint()}
function dismissWalkHint(){dismissSwipeCoach();const hint=document.getElementById('walkHint');if(hint)hint.hidden=true;try{sessionStorage.setItem('loop-walk-hint','seen')}catch{}}
function dismissSwipeCoach(){if(swipeHintTimer!==null){clearTimeout(swipeHintTimer);swipeHintTimer=null}const coach=document.getElementById('swipeCoach');if(coach)coach.hidden=true;try{localStorage.setItem('loop-swipe-coach-v1','seen')}catch{}}
function setupSwipeCoach(){const coach=document.getElementById('swipeCoach');if(!coach||window.innerWidth>760)return;try{if(localStorage.getItem('loop-swipe-coach-v1'))return}catch{}if(swipeHintTimer!==null)return;coach.hidden=false;swipeHintTimer=setTimeout(()=>{swipeHintTimer=null;coach.hidden=true;try{localStorage.setItem('loop-swipe-coach-v1','seen')}catch{}},6500)}
function setupWalk(){if(!walkInitialized){walkX=window.innerWidth>760?.5:.34;walkInitialized=true}paintWalk();setupSwipeCoach();const view=document.getElementById('walkViewport');if(!view)return;try{if(sessionStorage.getItem('loop-walk-hint'))document.getElementById('walkHint').hidden=true}catch{}let drag=null,moved=false,suppressClick=false;view.onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,start:e.clientX};moved=false;view.setPointerCapture(e.pointerId)};view.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x;if(Math.abs(e.clientX-drag.start)>6)moved=true;if(moved){dismissWalkHint();document.getElementById('walkScene').classList.add('dragging');const c=walkBounds(view.clientWidth,view.clientHeight,walkX);walkX=Math.max(view.clientWidth/c.w/2,Math.min(1-view.clientWidth/c.w/2,walkX-dx/c.w));walkActive=DEPARTMENTS.reduce((a,d)=>Math.abs(d.x/100-walkX)<Math.abs(a.x/100-walkX)?d:a).id;requestWalkPaint()}drag.x=e.clientX};view.onpointerup=e=>{if(!drag)return;if(moved){paintWalk();suppressClick=true;dismissWalkHint();setTimeout(()=>suppressClick=false,0)}else{const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-department]');if(target){suppressClick=true;enterWalkStore(target.dataset.department);setTimeout(()=>suppressClick=false,0)}}drag=null;document.getElementById('walkScene')?.classList.remove('dragging')};view.onpointercancel=()=>{drag=null;document.getElementById('walkScene')?.classList.remove('dragging')};view.onclick=e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation()}};view.onkeydown=e=>{if(e.target!==view)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();stepWalk(e.key==='ArrowLeft'?-1:1)}};}
function stepWalk(direction){const i=walkStops.indexOf(walkActive),next=Math.max(0,Math.min(walkStops.length-1,i+direction));walkTo(walkStops[next])}
function walkMap(){modal(`<div class="walk-map-content"><span class="eyebrow">LOOP / ONE STORE</span><h2>أقسام المحل</h2><p>كل ما تحتاجه في محل واحد. اختر القسم لتصفّح منتجاته.</p><img src="assets/loop-shop-interior.png" alt="علاقات الملابس ورفوف الأحذية والحقائب داخل محل LOOP"><nav>${DEPARTMENTS.map(d=>`<button data-action="walk-map-target" data-department="${d.id}"><strong>${d.name}</strong><small>${departmentProducts(d.id).length} قطعة</small><span>تسوّق القسم ←</span></button>`).join('')}</nav><p class="brand-concept-note">محل توضيحي تفاعلي. المنتجات والأسعار والطلبات تجريبية.</p></div>`)}
async function fullscreenWalk(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('الجولة تملأ مساحة المتصفح المتاحة على جهازك.')}catch{toast('تعذّر تفعيل ملء الشاشة؛ يمكنك متابعة الجولة هنا.')}}
function enterWalkStore(id){if(!DEPARTMENTS.some(d=>d.id===id))return;walkActive=id;dismissWalkHint();closeLayers();location.hash='#room/'+id;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='walk-target'||a==='walk-map-target')enterWalkStore(b.dataset.department);if(a==='walk-step')stepWalk(+b.dataset.direction);if(a==='walk-map')walkMap();if(a==='walk-fullscreen')fullscreenWalk();if(a==='walk-dismiss')dismissWalkHint();if(a==='walk-enter')enterWalkStore(walkActive)});
window.addEventListener('resize',()=>{if(document.getElementById('walkViewport'))requestWalkPaint()});
document.addEventListener('fullscreenchange',()=>{const b=document.getElementById('walkFullscreen');if(b){b.setAttribute('aria-label',document.fullscreenElement?'الخروج من ملء الشاشة':'تفعيل ملء الشاشة');b.textContent=document.fullscreenElement?'⊡':'⛶'}requestWalkPaint()});
